import{_ as a,o as s,c as t,a3 as o}from"./chunks/framework.DH50UWNB.js";const p=JSON.parse('{"title":"Questions","description":"","frontmatter":{},"headers":[],"relativePath":"start/questions.md","filePath":"start/questions.md"}'),n={name:"start/questions.md"};function r(i,e,l,h,c,d){return s(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="questions" tabindex="-1">Questions <a class="header-anchor" href="#questions" aria-label="Permalink to &quot;Questions&quot;">​</a></h1><p>Short answers to what people ask before they install Wake.</p><h2 id="which-systems-does-wake-run-on" tabindex="-1">Which systems does Wake run on? <a class="header-anchor" href="#which-systems-does-wake-run-on" aria-label="Permalink to &quot;Which systems does Wake run on?&quot;">​</a></h2><p>macOS, Linux, and Windows through WSL 2, on amd64 or arm64, with Docker. On Windows, Wake installs and runs inside a WSL 2 Linux distribution; see <a href="/wake-dist/docs/start/install#windows-with-wsl-2">Windows with WSL 2</a>.</p><h2 id="is-there-a-hosted-version" tabindex="-1">Is there a hosted version? <a class="header-anchor" href="#is-there-a-hosted-version" aria-label="Permalink to &quot;Is there a hosted version?&quot;">​</a></h2><p>No. Wake runs only on a machine you own, and its license does not allow offering it to others as a hosted service; see <a href="/wake-dist/docs/start/install">Install Wake</a> and <a href="/wake-dist/docs/reference/license">License</a>.</p><h2 id="who-counts-toward-the-3-people" tabindex="-1">Who counts toward the 3 people? <a class="header-anchor" href="#who-counts-toward-the-3-people" aria-label="Permalink to &quot;Who counts toward the 3 people?&quot;">​</a></h2><p>Every person who uses Wake for you and your company, however many installations you run, and whatever their role: owners, members and viewers. Someone who uses Wake through a bot or a shared tool counts too. On each installation, every active account counts; pending invitations, agents, personal access tokens and OAuth clients never count, and a disabled account frees its place; see <a href="/wake-dist/docs/run/sign-up#free-plan-accounts">Free plan accounts</a> and <a href="/wake-dist/docs/reference/license#the-free-plan">License</a>.</p><h2 id="can-a-teammate-use-my-local-installation" tabindex="-1">Can a teammate use my local installation? <a class="header-anchor" href="#can-a-teammate-use-my-local-installation" aria-label="Permalink to &quot;Can a teammate use my local installation?&quot;">​</a></h2><p>No. A local installation answers only on your machine, at <code>localhost</code>. For teammates on other machines, install Wake on a server they can reach with <code>--domain</code>, which serves it over HTTPS; see <a href="/wake-dist/docs/run/install-options#install-on-a-domain">Install on a domain</a>.</p><h2 id="what-happens-past-3-people" tabindex="-1">What happens past 3 people? <a class="header-anchor" href="#what-happens-past-3-people" aria-label="Permalink to &quot;What happens past 3 people?&quot;">​</a></h2><p>Each installation refuses its fourth account, by password, invitation or sign-in provider, and says how to free a place: <code>wake-server accounts disable &lt;email&gt;</code>; see <a href="/wake-dist/docs/run/sign-up#free-plan-accounts">Free plan accounts</a>.</p>',12)])])}const m=a(n,[["render",r]]);export{p as __pageData,m as default};
